nasal.script:
#
# Other nasal code you may have in this script section
# . . 
# . . 
#

##
# Setup of modifier (shift)
#
            # Set listener only on first run of this file
			var init = !contains(caller(0)[0], "init");
			var jslistener = func init and call(setlistener, arg);

            # Arrange property node for modifier (shift) button
            var modPath = "/devices/status/joysticks/modifier";
			var mod = 0;
			var m = props.globals.initNode(modPath, mod, "INT");
			jslistener(m, func(n) mod = n.getValue());

##
# Load the demultiplexer
#
            var demux = "dmx"; # Namespace for demultiplexer. Change name here only in case of collision.

            var bdn = func() {}; # stub function until demultiplexer is loaded
            var bup = func() {}; # stub function until demultiplexer is loaded

            if (globals[demux] == nil) {
                var fghome = getprop("/sim/fg-home");
                if (fghome != nil) {
                    var file = fghome ~ "/Input/Joysticks/cdmux.nas";
                    if (io.stat(file) != nil) {
                        io.load_nasal(file, demux);
                        print('Loaded ' ~ file);
                        }
                    }
                }

            # Load the demultiplexer setup for the current aircraft and joystick
            var hidname = 'VKB_Gunfighter_MCG_Ultimate'; # Name of the subdir for demux conf files
            var load_dmx_config = globals[demux]["load_dmx_config"];

            if (load_dmx_config(hidname)) {
                # Demultiplexer is loaded. Connect to its methods for button down/up
                var bdn = globals[demux]["bdn"];
                var bup = globals[demux]["bup"];
                }
